<script setup lang="ts">
import {onMounted,onBeforeUnmount,ref} from 'vue';import {LockKeyhole,ShieldCheck,KeyRound,Layers3,LoaderCircle} from 'lucide-vue-next';import App from './App.vue';import AccountMenu from './AccountMenu.vue';
interface AuthStatus{authenticated:boolean;setupRequired:boolean;legacyAvailable:boolean;legacyFilePresent:boolean;username:string;encrypted:boolean}
const status=ref<AuthStatus|null>(null),loading=ref(true),busy=ref(false),error=ref(''),notice=ref('');
const username=ref('admin'),password=ref(''),confirm=ref(''),token=ref(''),importExisting=ref(false),changing=ref(false),currentPassword=ref(''),newPassword=ref(''),confirmNew=ref('');
async function auth(path:string,body?:object){const response=await fetch('/api/auth/'+path,{method:body?'POST':'GET',credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const data=await response.json();if(!response.ok)throw new Error(data.message||'请求失败');return data}
async function refresh(){try{status.value=await auth('status');if(status.value?.authenticated)username.value=status.value.username;error.value=''}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
async function submit(){if(busy.value)return;error.value='';if(status.value?.setupRequired&&password.value!==confirm.value){error.value='两次密码不一致';return}busy.value=true;try{const data=await auth(status.value?.setupRequired?'setup':'login',{username:username.value,password:password.value,token:token.value,importExisting:importExisting.value});password.value='';confirm.value='';token.value='';notice.value='';await refresh();if(!status.value?.authenticated&&data.authenticated)error.value='会话未建立，请确认浏览器允许Cookie'}catch(e){error.value=(e as Error).message;password.value='';confirm.value=''}finally{busy.value=false}}
function clearPasswords(){password.value='';confirm.value='';currentPassword.value='';newPassword.value='';confirmNew.value=''}
async function logout(){if(busy.value)return;busy.value=true;try{await auth('logout',{});clearPasswords();channel?.postMessage('logout');status.value=null;changing.value=false;await refresh()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function changePassword(){error.value='';if(newPassword.value!==confirmNew.value){error.value='两次新密码不一致';return}busy.value=true;try{await auth('password',{currentPassword:currentPassword.value,newPassword:newPassword.value});currentPassword.value='';newPassword.value='';confirmNew.value='';changing.value=false;status.value=null;channel?.postMessage('password');notice.value='密码已修改，请重新登录。其他会话也已退出。';await refresh()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function expired(){if(status.value?.authenticated){status.value={...status.value,authenticated:false};changing.value=false;clearPasswords();notice.value='会话已过期，请重新登录';void refresh()}}
const channel=typeof BroadcastChannel!=='undefined'?new BroadcastChannel('aom-auth'):null;
function sessionMessage(){if(status.value?.authenticated)void refresh()}
channel?.addEventListener('message',sessionMessage);
function visibility(){if(document.visibilityState==='visible')void refresh()}
let timer:ReturnType<typeof setInterval>;
onMounted(()=>{void refresh();window.addEventListener('aom:unauthorized',expired);document.addEventListener('visibilitychange',visibility);timer=setInterval(()=>{if(status.value?.authenticated)void refresh()},60000)});
onBeforeUnmount(()=>{clearInterval(timer);window.removeEventListener('aom:unauthorized',expired);document.removeEventListener('visibilitychange',visibility);channel?.close()});
</script>
<template>
 <div v-if="loading" class="auth-screen"><LoaderCircle class="spin" :size="30"/><p>正在连接本地工作空间…</p></div>
 <template v-else-if="status?.authenticated">
  <App v-show="!changing"><template #account><AccountMenu :username="status.username" :busy="busy" :error="!changing?error:undefined" @password="changing=true;error=''" @logout="logout"/></template></App>
  <div v-if="status.legacyFilePresent&&!changing" class="legacy-data-notice" role="status">现有 app.db 仍是明文副本。核对加密数据后，请妥善处理该文件及旧备份。<button @click="status.legacyFilePresent=false">知道了</button></div>
  <div v-if="changing" class="auth-screen"><form class="auth-card" @submit.prevent="changePassword"><div class="auth-emblem"><KeyRound :size="26"/></div><h1>修改密码</h1><p>同时重新加密数据，所有会话将退出。</p><div v-if="error" class="error-banner" role="alert">{{error}}</div><label>当前密码<input v-model="currentPassword" type="password" autocomplete="current-password" required maxlength="128"/></label><label>新密码<input v-model="newPassword" type="password" autocomplete="new-password" required minlength="12" maxlength="128"/></label><label>确认新密码<input v-model="confirmNew" type="password" autocomplete="new-password" required minlength="12" maxlength="128"/></label><button class="primary full" :disabled="busy">{{busy?'正在重新加密…':'保存新密码'}}</button><button type="button" class="secondary full" :disabled="busy" @click="changing=false;clearPasswords();error='' ">返回工作空间</button><p class="auth-footnote">请保管密码。丢失密码无法解密数据；原备份仍需要创建备份时的密码。</p></form></div>
 </template>
 <div v-else class="auth-screen"><form class="auth-card" @submit.prevent="submit"><div class="auth-brand"><Layers3 :size="25"/><strong>AOM</strong><span>机房数字孪生</span></div><div class="auth-emblem"><LockKeyhole :size="27"/></div><h1>{{status?.setupRequired?'创建管理员账号':'登录工作空间'}}</h1><p>{{status?.setupRequired?'设置一个独立密码，用于登录及保护本地数据。':'输入账号和密码，解锁本地加密数据。'}}</p><div v-if="notice" class="info-banner" role="status">{{notice}}</div><div v-if="error" class="error-banner" role="alert">{{error}}</div>
  <template v-if="status"><label v-if="status.setupRequired">初始化令牌<input v-model="token" autocomplete="off" required placeholder="从后台控制台复制"/></label><label>账号<input v-model="username" autocomplete="username" required minlength="3" maxlength="64" spellcheck="false"/></label><label>密码<input v-model="password" type="password" :autocomplete="status.setupRequired?'new-password':'current-password'" required :minlength="status.setupRequired?12:undefined" maxlength="128"/></label><label v-if="status.setupRequired">确认密码<input v-model="confirm" type="password" autocomplete="new-password" required minlength="12" maxlength="128"/></label>
  <label v-if="status.setupRequired&&status.legacyAvailable" class="auth-checkbox"><input v-model="importExisting" type="checkbox" required/><span>导入现有 app.db 并创建加密副本；原文件保留，我会在核对后处理明文和旧备份。</span></label><button class="primary full" :disabled="busy"><LoaderCircle v-if="busy" class="spin" :size="16"/>{{busy?'正在处理…':status.setupRequired?'创建账号并加密':'登录'}}</button><p v-if="status.setupRequired" class="auth-footnote">密码至少12字节。密码丢失无法找回数据，请单独妥善保管。</p></template><button v-else type="button" class="secondary full" @click="refresh">重新连接</button>
  <div class="auth-security"><ShieldCheck :size="14"/>数据加密保存 · 不保存明文密码</div>
 </form></div>
</template>
